/**
 * TaskStatus represents the state of a task in its lifecycle.
 */
export type TaskStatus = number /* int */;
export const TaskStatusUnknown: TaskStatus = 0;
export const TaskStatusReceived: TaskStatus = 1;
export const TaskStatusQueued: TaskStatus = 2;
export const TaskStatusDispatched: TaskStatus = 3;
export const TaskStatusPreparing: TaskStatus = 4;
export const TaskStatusServing: TaskStatus = 5;
export const TaskStatusSettingUp: TaskStatus = 6;
export const TaskStatusRunning: TaskStatus = 7;
export const TaskStatusCancelling: TaskStatus = 8;
export const TaskStatusUploading: TaskStatus = 9;
export const TaskStatusCompleted: TaskStatus = 10;
export const TaskStatusFailed: TaskStatus = 11;
export const TaskStatusCancelled: TaskStatus = 12;
/**
 * Infra defines where a task should run.
 */
export type Infra = string;
export const InfraPrivate: Infra = "private";
export const InfraCloud: Infra = "cloud";
export const InfraPrivateFirst: Infra = "private_first";
/**
 * TaskLogType defines the type of task log.
 */
export type TaskLogType = number /* int */;
export const TaskLogTypeBuild: TaskLogType = 0;
export const TaskLogTypeRun: TaskLogType = 1;
export const TaskLogTypeServe: TaskLogType = 2;
export const TaskLogTypeSetup: TaskLogType = 3;
export const TaskLogTypeTask: TaskLogType = 4;
/**
 * TaskAction defines an action to execute when a task reaches a specific status.
 */
export interface TaskAction {
  key: string;
  on: string;
  params?: any;
}
/**
 * TaskMetadata holds optional metadata attached to a task.
 */
export interface TaskMetadata {
  action?: TaskAction;
}
export type TeamType = string;
export const TeamTypePersonal: TeamType = "personal";
export const TeamTypeTeam: TeamType = "team";
export const TeamTypeSystem: TeamType = "system";
export type TeamStatus = string;
export const TeamStatusActive: TeamStatus = "active";
export const TeamStatusSuspended: TeamStatus = "suspended";
export const TeamStatusTerminated: TeamStatus = "terminated";
export type TeamRole = string;
export const TeamRoleOwner: TeamRole = "owner";
export const TeamRoleAdmin: TeamRole = "admin";
export const TeamRoleMember: TeamRole = "member";
/**
 * ToolCallType represents the type field on a tool call (wire format).
 */
export type ToolCallType = string;
/**
 * ToolParamType represents a JSON Schema parameter type for tool definitions.
 */
export type ToolParamType = string;
/**
 * Tool call types
 */
export const ToolTypeFunction: ToolCallType = "function";
/**
 * Tool parameter types
 */
export const ToolParamTypeObject: ToolParamType = "object";
/**
 * Tool parameter types
 */
export const ToolParamTypeString: ToolParamType = "string";
/**
 * Tool parameter types
 */
export const ToolParamTypeInteger: ToolParamType = "integer";
/**
 * Tool parameter types
 */
export const ToolParamTypeNumber: ToolParamType = "number";
/**
 * Tool parameter types
 */
export const ToolParamTypeBoolean: ToolParamType = "boolean";
/**
 * Tool parameter types
 */
export const ToolParamTypeArray: ToolParamType = "array";
/**
 * Tool parameter types
 */
export const ToolParamTypeNull: ToolParamType = "null";
/**
 * ToolCall represents a tool call from an LLM response (wire format)
 * This is a transport object for parsing LLM responses, not a database model
 */
export interface ToolCall {
  id: string;
  type: ToolCallType; // "function"
  function: ToolCallFunction;
}
/**
 * ToolCallFunction contains the function name and arguments from an LLM tool call
 */
export interface ToolCallFunction {
  name: string;
  arguments: StringEncodedMap;
}
export interface Aux {
  name: string;
  arguments: any;
}
/**
 * LLMUsage contains token usage and performance metrics from an LLM response
 */
export interface LLMUsage {
  stop_reason: string;
  time_to_first_token: number /* float64 */;
  tokens_per_second: number /* float64 */;
  prompt_tokens: number /* int */;
  completion_tokens: number /* int */;
  total_tokens: number /* int */;
  reasoning_tokens: number /* int */;
  reasoning_time: number /* float64 */;
}
/**
 * FileRef is a lightweight reference to a file with essential metadata.
 * Used in chat inputs/context instead of full File objects.
 */
export interface FileRef {
  id?: string;
  uri: string;
  filename: string;
  content_type: string;
  size?: number /* int64 */;
}
/**
 * Tool represents a tool definition for LLM function calling
 */
export interface Tool {
  type: ToolCallType;
  function: ToolFunction;
}
export interface ToolFunction {
  name: string;
  description: string;
  parameters?: ToolParameters;
  required?: string[];
}
export interface ToolParameters {
  type: ToolParamType;
  title: string;
  properties?: ToolParameterProperties;
  required?: string[];
}
export type ToolParameterProperties = { [key: string]: ToolParameterProperty};
export interface ToolParameterProperty {
  type: ToolParamType;
  title: string;
  description: string;
  properties?: ToolParameterProperties;
  items?: ToolParameterProperty;
  required?: string[];
}
export type Role = string;
export const RoleGuest: Role = "guest";
export const RoleUser: Role = "user";
export const RoleAdmin: Role = "admin";
export const RoleSystem: Role = "system";
/**
 * UtilityConfig defines a flow utility node — gate, selector, merge, or custom CEL.
 */
export interface UtilityConfig {
  preset: string;
  expression?: string;
  gate?: GateCondition;
  selector?: SelectorConfig;
  constant?: any;
}
